  "anomalies": [
    {
      "category": "other",
      "components": ["U2"],
      "pins": ["U2.10", "U2.11", "U2.12"],
      "nets": ["VCC", "GND"],
      "observed": "On the display sheet, BS0 (pin 10) is tied to VCC, while BS1 (pin 11) and BS2 (pin 12) are tied to GND. This straps the SSD1306 for a non-I2C interface, even though its data pins are wired for I2C.",
      "expected": "The SSD1306 interface straps should be BS0=GND, BS1=VCC, BS2=GND, selecting I2C mode.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "U2 pins BS0 (10), BS1 (11), and BS2 (12) are shown strapped to VCC, GND, and GND respectively (display sheet, page 3)."
        },
        {
          "source": "spec",
          "quote": "BS0 (pin 10) → GND; BS1 (pin 11) → VCC; BS2 (pin 12) → GND"
        },
        {
          "source": "spec",
          "quote": "That BS2,BS1,BS0 = 0,1,0 strapping, together with D0→DISP_SCL and D1+D2 tied together →DISP_SDA, is the SSD1306's documented I2C-mode pin configuration."
        }
      ],
      "impact": "The display controller will be configured for a different bus mode than the MCU wiring provides, so the MCU is unlikely to communicate with or control the OLED.",
      "confidence": 0.97
    }
  ],
  "summary": "The display's interface-select pins are strapped differently from the specified I2C configuration. Because its data pins are wired for I2C, the OLED is unlikely to operate as intended."
}

